<script setup lang="ts">
import{computed,ref,watch}from'vue';import MValueBridge from './MValueBridge.vue';import type{MTransferProps}from'./types';import{useReferenceConfig}from'./locale';
const props=withDefaults(defineProps<MTransferProps>(),{filterable:true});const emit=defineEmits<{ 'update:modelValue':[value:string[]];change:[value:string[],direction:'left'|'right',moved:string[]] }>();const{t}=useReferenceConfig();const queries=ref(['','']),marked=ref<string[][]>([[],[]]);
const sides=computed(()=>[props.options.filter(option=>!props.modelValue.includes(option.value)),props.options.filter(option=>props.modelValue.includes(option.value))]);
function visible(side:number){return sides.value[side]!.filter(option=>option.label.toLocaleLowerCase().includes(queries.value[side]!.toLocaleLowerCase()));}
function toggleAll(side:number,event:Event){const checked=(event.target as HTMLInputElement).checked;marked.value[side]=checked?visible(side).filter(option=>!option.disabled).map(option=>option.value):[];}
function move(side:number){if(props.disabled||props.readonly)return;const available=new Set(sides.value[side]!.filter(option=>!option.disabled).map(option=>option.value));const moved=marked.value[side]!.filter(value=>available.has(value));if(!moved.length)return;const next=side===0?[...new Set([...props.modelValue,...moved])]:props.modelValue.filter(value=>!moved.includes(value));emit('update:modelValue',next);emit('change',next,side===0?'right':'left',moved);}
watch(()=>[props.modelValue,props.options],()=>{for(const side of [0,1])marked.value[side]=marked.value[side]!.filter(value=>sides.value[side]!.some(option=>option.value===value&&!option.disabled));},{deep:true});
</script>
<template><div class="ui-ri" role="group" :aria-label="label"><span class="ui-ri__label">{{label}}</span><div class="ui-ri-transfer"><template v-for="side in [0,1]" :key="side"><section class="ui-ri__panel"><h4>{{titles?.[side]||(side===0?t('transfer.source','待选项目'):t('transfer.target','已选项目'))}} {{sides[side]!.length}}</h4><input v-if="filterable" v-model="queries[side]" class="ui-ri__control" :aria-label="t('search','搜索')+(titles?.[side]||(side===0?t('transfer.source','待选项目'):t('transfer.target','已选项目')))"><label class="ui-ri__row"><input type="checkbox" :disabled="disabled||readonly" :checked="!!visible(side).filter(option=>!option.disabled).length&&visible(side).filter(option=>!option.disabled).every(option=>marked[side]!.includes(option.value))" @change="toggleAll(side,$event)">{{t('transfer.selectAll','选择当前结果')}}</label><ul class="ui-ri__list"><li v-for="option in visible(side)" :key="option.value"><label class="ui-ri__row"><input v-model="marked[side]" type="checkbox" :value="option.value" :disabled="disabled||readonly||option.disabled">{{option.label}}</label></li></ul><p v-if="!visible(side).length">{{t('empty','暂无数据')}}</p><button type="button" class="ui-ri__button" :disabled="disabled||readonly||!marked[side]!.length" @click="move(side)">{{side===0?t('transfer.add','移入已选'):t('transfer.remove','移回待选')}}</button></section></template></div><MValueBridge v-bind="props" :values="modelValue" :error="modelValue.some(value=>!options.some(option=>option.value===value))?t('transfer.invalid','存在无效项目。'):''"/></div></template>
<style scoped>.ui-ri-transfer{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.ui-ri-transfer h4{margin:0 0 10px}.ui-ri-transfer .ui-ri__panel{display:grid;gap:12px}.ui-ri-transfer li{min-height:36px}@media(max-width:480px){.ui-ri-transfer{grid-template-columns:minmax(0,1fr)}}@media(pointer:coarse){.ui-ri-transfer li{min-height:44px}}</style>
